@gene('Z143b', 'how much closer a step brings me to the goals; stay on spawn while healing; when carrying gems or healing, steps beside enemy champions (cached tiles) count less', parents=['s4'])
def progress(t: Tile) -> Num:
    if HEALING and me().pos in my_spawn():
        return 0
    f = goal_field()
    d = at(f, me().pos) - at(f, t)
    if d > 0 and (HEALING or gems() > 0):
        d -= 0.6 * count(dist(x, t) <= 2 for x in ECH)
    return d
