@gene('new', 'position of a weak nearby enemy champion worth chasing (invalid if none)', parents=['Z143b'])
def chase_target() -> Tile:
    mp = me().pos
    u = best(enemies(), lambda e: (100 - e.health_frac * 100 + min(unit_gems(e), 50)) if e.is_champion and e.health_frac < 0.35 and dist(e.pos, mp) <= 4 else -1000)
